import { readFile } from "node:fs/promises";
import path from "node:path";

const expectedPages = new Map([
  ["mvc-core-deck.pdf", 14],
  ["mvc-core-deck-no-logos.pdf", 14],
  ["mvc-mission-deck.pdf", 15],
  ["mvc-mission-deck-no-logos.pdf", 15],
]);

const failures = [];
for (const [filename, expected] of expectedPages) {
  const pdfPath = path.join(process.cwd(), "public", "downloads", filename);
  const pdf = (await readFile(pdfPath)).toString("latin1");
  // The control-room PDFs are generated by the shared raster/ReportLab
  // exporter, which writes one uncompressed Page dictionary per slide.
  const actual = pdf.match(/\/Type\s*\/Page(?!s)\b/g)?.length ?? 0;
  if (actual !== expected) {
    failures.push(`${filename}: expected ${expected} pages, found ${actual}`);
  }
}

if (failures.length > 0) {
  console.error(`Deck PDF page-count check failed:\n${failures.join("\n")}`);
  process.exitCode = 1;
} else {
  console.log("Deck PDF page-count check passed.");
}
